package vmcompat;
import java.util.*;import java.nio.file.*;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;
/** Expanded production shader assets and the same compatibility/compiler/linker path. */
public final class StartupShadersTests {
 public static void main(String[]args)throws Exception{
  if(!GLFW.glfwInit())throw new AssertionError();GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);long w=Context.createWindow(32,32,"Viewpoint program catalog",0,0);Context.makeCurrent(w);Context.capabilities();
  Class<?> packs=Class.forName("viewpoint.platform.ShaderPacks"),loader=Class.forName("viewpoint.platform.Shaders");var load=loader.getDeclaredMethod("load",String.class);load.setAccessible(true);var pairs=ShaderCatalog.pairs(args[0]);List<String> errors=new ArrayList<>(),recipes=new ArrayList<>();int passed=0;
  for(String pack:System.getProperty("vmcompat.catalogPacks","normal,vivid").split(",")){packs.getMethod("useBuiltIn",String.class,String.class).invoke(null,pack,"low");Object active=packs.getMethod("active").invoke(null);Object selected=active.getClass().getField("pack").get(active);String actual=(String)selected.getClass().getField("id").get(selected);System.out.println("PACK requested="+pack+", actual="+actual);if(!pack.equals("normal")&&!actual.equals(pack))throw new AssertionError("Unexpected shader pack fallback");for(var row:pairs){int program=Shaders.glCreateProgram();List<Integer> shaders=new ArrayList<>();try{for(int i=1;i<=2;i++){Object source=load.invoke(null,row.get(i));var text=source.getClass().getDeclaredField("text");text.setAccessible(true);int shader=GL20.glCreateShader(i==1?GL20.GL_VERTEX_SHADER:GL20.GL_FRAGMENT_SHADER);shaders.add(shader);Shaders.vpSource(shader,(String)text.get(source));Shaders.glCompileShader(shader);if(GL20.glGetShaderi(shader,GL20.GL_COMPILE_STATUS)==0)throw new AssertionError(GL20.glGetShaderInfoLog(shader));Shaders.glAttachShader(program,shader);}Shaders.glLinkProgram(program);if(GL20.glGetProgrami(program,GL20.GL_LINK_STATUS)==0)throw new AssertionError(GL20.glGetProgramInfoLog(program));if(NativeSamplers.ENABLED&&java.util.Set.of("model_gbuffer.frag","model_shadow.frag","model_outline.frag","model_glass.frag","far.frag","far_shell.frag","gbuffer_shell.frag","far_shadow_shell.frag","vehicle_glass.frag").contains(row.get(2))){var plans=Packing.class.getDeclaredField("PLANS");plans.setAccessible(true);Object plan=((Map<?,?>)plans.get(null)).get(program);List<String> names=new ArrayList<>();if(plan!=null){var slots=plan.getClass().getDeclaredField("slots");slots.setAccessible(true);for(Object slot:(List<?>)slots.get(plan)){var name=slot.getClass().getDeclaredField("name");name.setAccessible(true);String n=(String)name.get(slot);if(n.startsWith("uAtlases")||n.startsWith("uTextures")||java.util.Set.of("uMainDepth","uLight","uRelief","uReliefWater","uGlassScene","uFlowCar","uFlowPull","uVehicleTops","uTexture").contains(n))throw new AssertionError("Heavy resource imported by native recipe: "+n);names.add(n);}}recipes.add(pack+" / "+row+" => "+(plan==null?"NATIVE_TEXTURES":names));}passed++;System.out.println("PROGRAM PASS "+pack+" / "+row);}catch(Throwable e){String message=pack+" / "+row+" : "+e;errors.add(message);System.out.println("PROGRAM FAIL "+message);}finally{Shaders.glDeleteProgram(program);for(int shader:shaders)GL20.glDeleteShader(shader);}}}
  Files.writeString(Path.of(System.getProperty("vmcompat.resultDir")).resolve("native-recipes.txt"),String.join("\n",recipes));Files.writeString(Path.of(System.getProperty("vmcompat.resultDir")).resolve("shader-catalog-errors.txt"),String.join("\n",errors));Context.destroyWindow(w);GLFW.glfwTerminate();System.out.println("CATALOG pairs="+pairs.size()+", linked="+passed+", failures="+errors.size());if(!errors.isEmpty())throw new AssertionError("Shader catalog failures: "+errors.size());
 }
}
